		void show(String message, Tone tone)
		{
			clear.stop();
			if (message == null || message.trim().isEmpty()) { setVisible(false); return; }
			setText(html(escape(message), widthPx));
			setForeground(toneColor(tone));
			setVisible(true);
			boolean inProgress = message.endsWith("...");
